function update(dt){if(!gameStarted||paused||dead||won)return;elapsed+=dt;player.shootCd=Math.max(0,player.shootCd-dt);player.flash=Math.max(0,player.flash-dt);player.invuln=Math.max(0,player.invuln-dt);if(toastTimer>0&& (toastTimer-=dt)<=0)$('toast').classList.remove('visible');if(bannerTimer>0&&(bannerTimer-=dt)<=0)$('objective-banner').classList.remove('show');let dx=(keys.d||keys.arrowright?1:0)-(keys.a||keys.arrowleft?1:0)+input.x,dy=(keys.s||keys.arrowdown?1:0)-(keys.w||keys.arrowup?1:0)+input.y;let len=Math.hypot(dx,dy);if(len>1){dx/=len;dy/=len}let sprint=keys.shift||input.sprint,speed=player.speed*(sprint?1.52:1);moveActor(player,dx*speed*dt,dy*speed*dt,player.r);if(player.moving&&!input.hasAimed&&!mouse.active)player.angle=Math.atan2(dy,dx);if(input.aiming&&Math.hypot(input.aimX,input.aimY)>.18){player.angle=Math.atan2(input.aimY,input.aimX);input.hasAimed=true}else if(mouse.active&&(mouse.down||!input.hasAimed)){let worldMouse={x:mouse.x+camera.x,y:mouse.y+camera.y};player.angle=Math.atan2(worldMouse.y-player.y,worldMouse.x-player.x);input.hasAimed=false}if(mouse.down||input.fire)fire();const safeCamp=dist(player,zones[0])<zones[0].r;
