iption').textContent='You have the artifact. Get back to Skadovsk alive and collect your reward.';$('task-state-label').textContent='RETURN TO THE SKADOVSK';$('task-check').textContent='02';$('mission-progress-bar').style.width='58%';$('artifact-count').textContent='1';audio(820,.25,'sine');return}toast('NOTHING TO USE HERE')}
