 function useMedkit(){if(!gameStarted||paused)return;if(player.medkits<=0){toast('АПТЕЧЕК НЕТ');return}if(player.hp>=100){toast('ЗДОРОВЬЕ В НОРМЕ');return}player.medkits--;player.hp=Math.min(100,player.hp+38);inventoryDirty=true;toast('АПТЕЧКА ИСПОЛЬЗОВАНА · +38 ЗДОРОВЬЯ');audio(520,.16,'sine');updateUI()}
 function useWater(){if(!gameStarted||paused)return;if(player.water<=0){toast('ВОДА ЗАКОНЧИЛАСЬ');return}if(player.thirst>=100&&player.rad<=0){toast('ПИТЬ НЕ ХОЧЕТСЯ');return}player.water--;player.thirst=Math.min(100,player.thirst+45);player.rad=Math.max(0,player.rad-8);inventoryDirty=true;toast('ВОДА ВЫПИТА · ЖАЖДА УТОЛЕНА');audio(520,.16,'sine');updateUI()}
 function useFood(){if(!gameStarted||paused)return;if(player.food<=0){toast('ПАЙКИ ЗАКОНЧИЛИСЬ');return}if(player.hunger>=100){toast('ТЫ УЖЕ СЫТ');return}player.food--;player.hunger=Math.min(100,player.hunger+42);inventoryDirty=true;toast('ПАЁК СЪЕДЕН · СЫТОСТЬ ВОССТАНОВЛЕНА');audio(440,.16,'sine');updateUI()}
 function safeTeleport(point){const candidates=[{x:point.x,y:point.y}];for(let radius=18;radius<=108;radius+=18)for(let i=0;i<12;i++){let a=i*Math.PI/6;candidates.push({x:point.x+Math.cos(a)*radius,y:point.y+Math.sin(a)*radius})}let spot=candidates.find(p=>!blockedByWorld(p.x,p.y,player.r)&&!actorBlocked(player,p.x,p.y,player.r));return spot}
-function interact(){if(!gameStarted||paused)return;let gate=gates.map(g=>({gate:g,d:dist(player,g)})).filter(item=>item.d<110).sort((a,b)=>a.d-b.d)[0]?.gate;if(gate){let spot=safeTeleport(gate.to);if(!spot){toast('ПУТЬ ЗАВАЛЕН · ПОПРОБУЙ ЕЩЁ РАЗ');return}player.x=spot.x;player.y=spot.y;player.moving=false;player.invuln=2.5;bullets.length=0;for(let enemy of enemies){if(!enemy.dead){enemy.state='patrol';enemy.alert=0;enemy.target=null}}camera.x=clamp(player.x-cw/2,0,W-cw);camera.y=clamp(player.y-ch/2,0,H-ch);let destination=locationName(gate.destination);toast('ПЕРЕХОД · '+destination);$('location-name').textContent=destination;audio(360,.2,'sine');return}let person=civilians.find(n=>dist(player,n)<68);if(person){toast(person.name==='Veles'?'ВЕЛЕС: Держись троп и не лезь в аномалии.':'МАКАР: Старая железная дорога полна мутантов.');return}let target=null,d=74;for(let s of stash){let n=dist(player,s);if(!s.searched&&n<d){target=s;d=n}}if(target){target.searched=true;searchedCount++;let msg='НАЙДЕНО: '+(target.loot==='FIELD DRESSING'?'АПТЕЧКА':target.loot==='MEDKIT'?'АПТЕЧКА':target.loot.includes('FMJ')?'9 ПАТРОНОВ 7,62×39':'350 ₽');if(target.loot==='FIELD DRESSING'||target.loot==='MEDKIT'){player.medkits++;$('medkit-count').textContent=player.medkits}else if(target.loot.includes('FMJ'))player.reserve+=9;else if(target.loot.includes('350'))player.ru+=350;inventoryDirty=true;toast(msg);audio(620,.12,'sine');updateUI();return}if(!artifact.found&&dist(player,artifact)<92){artifact.found=true;player.artifacts=1;player.ru+=800;inventoryDirty=true;banner('АРТЕФАКТ НАЙДЕН · ВОЗВРАЩАЙСЯ В ЛАГЕРЬ');$('mission-title').textContent='Дорога домой';$('mission-copy').textContent='Артефакт у тебя. Вернись в Скадовск живым и получи награду.';$('survival-label').textContent='ВОЗВРАЩАЙСЯ В ЛАГЕРЬ';$('mission-progress-bar').style.width='58%';audio(820,.25,'sine');updateUI();return}toast('ЗДЕСЬ НЕЧЕГО ДЕЛАТЬ')}
