 await evaljs("document.querySelector('#inventory-close').click()");
 check('no runtime exceptions',errors.length===0,errors.join('; '));
 console.log('RESULT',JSON.stringify(checks)); ws.close(); process.exit(checks.every(c=>c.ok)?0:1);
