(async()=>{
  const tabs=await (await fetch('http://127.0.0.1:9223/json/list')).json();
  const tab=tabs.find(x=>x.type==='page'&&x.url.startsWith('http://127.0.0.1:8000/'));
  const ws=new WebSocket(tab.webSocketDebuggerUrl); let next=0; const pending=new Map();
  ws.addEventListener('message',e=>{const m=JSON.parse(e.data);if(m.id&&pending.has(m.id)){pending.get(m.id)(m);pending.delete(m.id)}});
  await new Promise((resolve,reject)=>{ws.addEventListener('open',resolve,{once:true});ws.addEventListener('error',reject,{once:true})});
  const call=(method,params={})=>new Promise(resolve=>{const id=++next;pending.set(id,resolve);ws.send(JSON.stringify({id,method,params}))});
  const evaljs=async expression=>(await call('Runtime.evaluate',{expression,returnByValue:true,awaitPromise:true})).result?.result?.value;
  const wait=ms=>new Promise(r=>setTimeout(r,ms));
  await call('Page.enable'); await call('Runtime.enable'); await call('Page.navigate',{url:'http://127.0.0.1:8000/'}); await wait(1000);
  const errors=[]; ws.addEventListener('message',e=>{const m=JSON.parse(e.data);if(m.method==='Runtime.exceptionThrown') errors.push(m.params.exceptionDetails.text)});
  const checks=[]; const check=(name,ok,detail='')=>{checks.push({name,ok,detail});console.log(`${ok?'PASS':'FAIL'} ${name}${detail?': '+detail:''}`)};
  const touch=async id=>{const p=await evaljs(`(()=>{let r=document.querySelector('#${id}').getBoundingClientRect();return {x:r.x+r.width/2,y:r.y+r.height/2}})()`);await call('Input.dispatchTouchEvent',{type:'touchStart',touchPoints:[{x:p.x,y:p.y,id:1}]});await call('Input.dispatchTouchEvent',{type:'touchEnd',touchPoints:[]});await wait(150)};
  const stick=async(dx,dy,ms)=>{const p=await evaljs(`(()=>{let r=document.querySelector('#stick').getBoundingClientRect();return {x:r.x+r.width/2,y:r.y+r.height/2}})()`);await call('Input.dispatchTouchEvent',{type:'touchStart',touchPoints:[{x:p.x,y:p.y,id:1}]});await call('Input.dispatchTouchEvent',{type:'touchMove',touchPoints:[{x:p.x+dx*30,y:p.y+dy*30,id:1}]});await wait(ms);await call('Input.dispatchTouchEvent',{type:'touchEnd',touchPoints:[]});await wait(100)};
  check('page loaded',await evaljs("document.title.includes('СЕРАЯ ЗОНА')"));
  await evaljs("document.querySelector('#start-button').click()"); await wait(100);
  check('game starts',await evaljs("document.querySelector('#title-overlay').classList.contains('hidden')"));
  await call('Emulation.setDeviceMetricsOverride',{width:390,height:844,deviceScaleFactor:1,mobile:true}); await call('Emulation.setTouchEmulationEnabled',{enabled:true,maxTouchPoints:1}); await wait(200);
  check('touch controls visible on mobile',await evaljs("getComputedStyle(document.querySelector('#touch-controls')).display!=='none'"));
  // Use the on-screen joystick to go around the camp buildings toward the supply crate.
  await stick(0,1,1600); await stick(1,0,1150); await stick(0,-1,1350);
  check('cache prompt reached',await evaljs("document.querySelector('#prompt-text').textContent.includes('ОБЫСКАТЬ')"),await evaljs("document.querySelector('#prompt-text').textContent"));
  await touch('touch-use');
  check('camp cache searched',await evaljs("document.querySelector('#cache-count').textContent==='1'"),await evaljs("document.querySelector('#toast').textContent"));
  await touch('touch-use');
  check('touch action activates camp transition',await evaljs("document.querySelector('#location-name').textContent==='ТИХАЯ МИЛЯ'"),await evaljs("document.querySelector('#location-name').textContent"));
  await evaljs("document.querySelector('#inventory-button').click()"); await wait(100);
  check('inventory opens on touch',await evaljs("!document.querySelector('#inventory-panel').classList.contains('hidden')"));
  await evaljs("document.querySelector('#inventory-close').click()");
  check('no runtime exceptions',errors.length===0,errors.join('; '));
  console.log('RESULT',JSON.stringify(checks)); ws.close(); process.exit(checks.every(c=>c.ok)?0:1);
})().catch(e=>{console.error(e);process.exit(1)});

