(async () => {
  const tabs = await (await fetch('http://127.0.0.1:9223/json/list')).json();
  const tab = tabs.find(x => x.type === 'page' && x.url.startsWith('http://127.0.0.1:8000/'));
  if (!tab) throw new Error('Game tab not found');
  const ws = new WebSocket(tab.webSocketDebuggerUrl);
  let id = 0;
  const pending = new Map();
  ws.addEventListener('message', event => {
    const message = JSON.parse(event.data);
    if (pending.has(message.id)) {
      pending.get(message.id)(message);
      pending.delete(message.id);
    }
  });
  await new Promise(resolve => ws.addEventListener('open', resolve, { once: true }));
  const call = (method, params = {}) => new Promise(resolve => {
    const requestId = ++id;
    pending.set(requestId, resolve);
    ws.send(JSON.stringify({ id: requestId, method, params }));
  });
  const finder = () => {
    const { trees, buildings } = window.__gameDebug;
    const blocked = (x, y) => {
      if (x < 35 || x > 2965 || y < 35 || y > 2165) return true;
      for (const tree of trees) if (Math.hypot(x - tree.x, y - tree.y) < 13 + tree.r * .62) return true;
      for (const b of buildings) {
        const dx = x - b.x, dy = y - b.y, c = Math.cos(-b.r), s = Math.sin(-b.r);
        const lx = dx * c - dy * s, ly = dx * s + dy * c;
        if (Math.abs(lx) < b.w / 2 + 13 && Math.abs(ly) < b.h / 2 + 13) return true;
      }
      return false;
    };
    const step = 8, sx = 2164, sy = 556, gx = 2050, gy = 730;
    const key = (x, y) => `${x},${y}`;
    const queue = [[sx, sy]], previous = new Map([[key(sx, sy), null]]);
    const dirs = [[step, 0], [-step, 0], [0, step], [0, -step], [step, step], [step, -step], [-step, step], [-step, -step]];
    let end = null;
    for (let i = 0; i < queue.length; i++) {
      const [x, y] = queue[i];
      if (Math.hypot(x - gx, y - gy) < 60) { end = [x, y]; break; }
      for (const [dx, dy] of dirs) {
        const nx = x + dx, ny = y + dy, k = key(nx, ny);
        if (previous.has(k) || blocked(nx, ny) || blocked(x + dx * .5, y + dy * .5)) continue;
        previous.set(k, [x, y]);
        queue.push([nx, ny]);
      }
    }
    if (!end) return { error: 'No route', reached: queue.length };
    const path = [];
    for (let point = end; point; point = previous.get(key(...point))) path.push(point);
    path.reverse();
    const waypoints = [path[0]];
    let lastDir = null;
    for (let i = 1; i < path.length; i++) {
      const dx = Math.sign(path[i][0] - path[i - 1][0]), dy = Math.sign(path[i][1] - path[i - 1][1]);
      const dir = `${dx},${dy}`;
      if (lastDir !== null && dir !== lastDir) waypoints.push(path[i - 1]);
      lastDir = dir;
    }
    waypoints.push(path[path.length - 1]);
    return { reached: queue.length, distance: path.length * step, endpoint: end, waypoints };
  };
  const result = await call('Runtime.evaluate', { expression: `(${finder.toString()})()`, returnByValue: true });
  console.log(result.result?.result?.value ?? JSON.stringify(result));
  ws.close();
})().catch(error => { console.error(error); process.exit(1); });

