(async()=>{
 const tabs=await(await fetch('http://127.0.0.1:9223/json/list')).json();
 const tab=tabs.find(x=>x.type==='page'&&x.url.startsWith('http://127.0.0.1:8000/'));
 if(!tab)throw new Error('Game tab not found');
 const ws=new WebSocket(tab.webSocketDebuggerUrl);let id=0;const pending=new Map();const errors=[];
 ws.addEventListener('message',e=>{const m=JSON.parse(e.data);if(m.method==='Runtime.exceptionThrown')errors.push(m.params.exceptionDetails.text);if(m.id&&pending.has(m.id)){pending.get(m.id)(m);pending.delete(m.id)}});
 await new Promise(r=>ws.addEventListener('open',r,{once:true}));
 const call=(method,params={})=>new Promise(r=>{const n=++id;pending.set(n,r);ws.send(JSON.stringify({id:n,method,params}))});
 const ev=async expression=>(await call('Runtime.evaluate',{expression,returnByValue:true,awaitPromise:true})).result?.result?.value;
 await call('Page.enable');await call('Runtime.enable');await call('Emulation.setDeviceMetricsOverride',{width:390,height:844,deviceScaleFactor:1,mobile:true});await call('Emulation.setTouchEmulationEnabled',{enabled:true,maxTouchPoints:1});
 await call('Page.navigate',{url:'http://127.0.0.1:8000/'});await new Promise(r=>setTimeout(r,1100));
 const before=await ev("JSON.stringify({title:document.title,start:!!document.querySelector('#start-button'),stick:!!document.querySelector('#stick'),touchUse:!!document.querySelector('#touch-use'),canvas:!!document.querySelector('#world'),debug:typeof window.__gameDebug})");
 await ev("document.querySelector('#start-button').click()");await new Promise(r=>setTimeout(r,500));
 const after=await ev("JSON.stringify({titleHidden:document.querySelector('#title-overlay').classList.contains('hidden'),canvasWidth:document.querySelector('#world').width,canvasHeight:document.querySelector('#world').height,mission:document.querySelector('#mission-title').textContent})");
 console.log(JSON.stringify({before:JSON.parse(before),after:JSON.parse(after),runtimeErrors:errors},null,2));ws.close();
})().catch(e=>{console.error(e);process.exit(1)});

